import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` per-line config text.

    Each line is split on its first "=", so values may themselves contain
    "=". Whitespace around the name and around the value is stripped.
    Blank lines, lines starting with "#" (after stripping), and lines
    without "=" are ignored. Key matching is exact and case-sensitive.
    If the key appears more than once, the last occurrence wins.
    Returns "" when the key is absent. A key present with no value also
    gives "". Does not read files; `text` is the whole config.
    """
    result = ""
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, val = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            result = val.strip()
    return result


def test_basic_lookup() -> None:
    text = "a=1\nb=2\nc=3"
    assert config_value(text, "a") == "1"
    assert config_value(text, "b") == "2"
    assert config_value(text, "c") == "3"


def test_absent_key() -> None:
    assert config_value("a=1\nb=2", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_stripped() -> None:
    assert config_value("  name  =  hello world  \n", "name") == "hello world"


def test_value_contains_equals() -> None:
    assert config_value("url=http://x.com/?q=1", "url") == "http://x.com/?q=1"


def test_empty_value() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_lines_without_equals_ignored() -> None:
    assert config_value("garbage\na=1\nmore garbage", "a") == "1"
    assert config_value("garbage", "garbage") == ""


def test_comments_and_blank_lines_ignored() -> None:
    text = "# a=commented\n\n   \n  # b=2\nc=3"
    assert config_value(text, "a") == ""
    assert config_value(text, "b") == ""
    assert config_value(text, "c") == "3"


def test_exact_key_match_not_prefix_or_suffix() -> None:
    text = "ab=1\nb=2\nabc=3"
    assert config_value(text, "a") == ""
    assert config_value(text, "b") == "2"
    assert config_value(text, "ab") == "1"


def test_case_sensitive() -> None:
    assert config_value("Key=1", "key") == ""
    assert config_value("Key=1", "Key") == "1"


def test_duplicate_key_last_wins() -> None:
    assert config_value("a=1\nb=2\na=3", "a") == "3"


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "a") == "1"
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


def test_trailing_newline() -> None:
    assert config_value("a=1\n", "a") == "1"


@pytest.mark.parametrize("key", ["", " "])
def test_empty_or_blank_key_not_found_in_normal_config(key: str) -> None:
    assert config_value("a=1\nb=2", key) == ""

